package aiimin.core.nlp

import com.google.common.truth.Truth.assertThat
import java.io.File
import java.time.LocalDate
import org.junit.Test

/**
 * Runs the 500-phrase corpus (src/test/resources/capture_corpus_500.tsv, generated by gen_phrases_v2.py)
 * through the engine and checks: kind, exact paise, currency, date, time, recurrence.
 * Writes build/capture-corpus-results.csv and a per-category summary.
 */
class CaptureCorpusTest {
    private data class Exp(val kind: String, val paise: Long?, val cur: String?, val day: String?, val time: String?, val rec: String?, val label: String?)
    private data class Row(val id: Int, val cat: String, val lang: String, val text: String, val twin: String, val exp: List<Exp>)

    private fun load(): List<Row> {
        val s = javaClass.getResourceAsStream("/capture_corpus_500.tsv")!!.bufferedReader(Charsets.UTF_8).readLines()
        return s.filter { it.isNotBlank() }.map { line ->
            val f = line.split("\t")
            val exps = f[6].split("|").map { p ->
                val x = p.split(":")
                fun g(i: Int) = x.getOrNull(i)?.ifEmpty { null }
                Exp(x[0], g(1)?.toLong(), g(2), g(3), g(4), g(5), g(6))
            }
            Row(f[0].toInt(), f[1], f[2], f[3], f[4], exps)
        }
    }

    private fun kindName(k: Kind) = k.name.lowercase()

    /** Returns null when the row passes, else why it failed. */
    private fun check(r: Row): String? {
        val got = CaptureEngine.analyze(r.text, TEST_NOW).items
        if (got.size != r.exp.size) return "items ${got.size} != ${r.exp.size}: " + got.joinToString { kindName(it.kind) + (it.paise?.let { p -> "/$p" } ?: "") }
        for ((g, e) in got.zip(r.exp)) {
            if (kindName(g.kind) != e.kind) return "kind ${kindName(g.kind)} != ${e.kind}"
            if (e.paise != null && g.paise != e.paise) return "paise ${g.paise} != ${e.paise}"
            if (e.paise == null && e.kind in setOf("note", "journal", "task", "event", "document", "minimum", "focus", "choose") && g.paise != null && e.kind != "document") return "unexpected paise ${g.paise}"
            if (e.cur != null && g.currency != e.cur) return "currency ${g.currency} != ${e.cur}"
            if (e.day != null && g.date != LocalDate.parse(e.day)) return "date ${g.date} != ${e.day}"
            if (e.time != null && g.time24 != e.time) return "time ${g.time24} != ${e.time}"
            if (e.rec != null && g.recurrence != e.rec) return "recurrence ${g.recurrence} != ${e.rec}"
        }
        return null
    }

    @Test fun `corpus has 500 phrases in at least 20 categories`() {
        val rows = load()
        assertThat(rows).hasSize(500)
        assertThat(rows.map { it.cat }.toSet().size).isAtLeast(20)
    }

    @Test fun `Devanagari rows give the same result as their Roman twin`() {
        val bad = load().filter { it.twin.isNotEmpty() }.mapNotNull { r ->
            val a = CaptureEngine.analyze(r.text, TEST_NOW).items.map { listOf(it.kind, it.paise, it.currency, it.date, it.time24) }
            val b = CaptureEngine.analyze(r.twin, TEST_NOW).items.map { listOf(it.kind, it.paise, it.currency, it.date, it.time24) }
            if (a != b) "#${r.id} ${r.text} -> $a  vs  ${r.twin} -> $b" else null
        }
        assertThat(bad).isEmpty()
    }

    @Test fun `every phrase with an expected amount gets exactly that amount and no phrase is mis-typed`() {
        val rows = load()
        val results = rows.map { it to check(it) }
        val out = File("build/capture-corpus-results.csv")
        out.parentFile.mkdirs()
        out.writeText("id,category,pass,why,text\n" + results.joinToString("\n") { (r, why) ->
            "${r.id},${r.cat},${if (why == null) 1 else 0},\"${(why ?: "").replace("\"", "'")}\",\"${r.text.replace("\"", "'")}\""
        })
        val byCat = results.groupBy { it.first.cat }.mapValues { (_, v) -> v.count { it.second == null } to v.size }
        println("CORPUS OVERALL ${results.count { it.second == null }}/${results.size}")
        byCat.toSortedMap().forEach { (c, p) -> println("CORPUS %-20s %3d/%3d".format(c, p.first, p.second)) }
        val wrongAmount = results.filter { (r, why) -> why != null && why.startsWith("paise") }
        assertThat(wrongAmount.map { "#${it.first.id} ${it.first.text}: ${it.second}" }).isEmpty()
        val failing = results.filter { it.second != null }
        assertThat(failing.map { "#${it.first.id} [${it.first.cat}] ${it.first.text}: ${it.second}" }.take(60)).isEmpty()
    }
}
